const path = require("path");

/** Filenames under assets/spike-audio (gitignored; generated by @intell/audio-fixtures). */
const SPIKE_WAV_NAMES = [
  "narration_90s.wav",
  "stem_a.wav",
  "stem_b.wav",
  "stem_c.wav",
  "bed_wind.wav",
  "bed_water.wav",
  "oneshot_1.wav",
  "oneshot_2.wav",
  "oneshot_3.wav",
  "oneshot_4.wav",
  "oneshot_5.wav",
  "oneshot_6.wav",
];

/**
 * When a require() targets a path under assets/spike-audio and the file is
 * missing (gitignored fixtures), Metro should load missingAsset.js instead of
 * failing the resolve. Existing WAVs fall through to the upstream resolver.
 *
 * @param {{
 *   originModulePath: string | undefined,
 *   moduleName: string,
 *   spikeRoot: string,
 *   missingSpikeAsset: string,
 *   existsSync: (p: string) => boolean,
 * }} args
 * @returns {{ type: "sourceFile", filePath: string } | null}
 */
function resolveSpikeAudioRequest({
  originModulePath,
  moduleName,
  spikeRoot,
  missingSpikeAsset,
  existsSync,
}) {
  if (!originModulePath) {
    return null;
  }
  const abs = path.isAbsolute(moduleName)
    ? moduleName
    : path.resolve(path.dirname(originModulePath), moduleName);
  const rel = path.relative(spikeRoot, abs);
  const insideSpike =
    rel !== "" && !rel.startsWith("..") && !path.isAbsolute(rel);
  if (insideSpike && !existsSync(abs)) {
    return { type: "sourceFile", filePath: missingSpikeAsset };
  }
  return null;
}

module.exports = { resolveSpikeAudioRequest, SPIKE_WAV_NAMES };
